import java.util.Scanner;
public class CountSetBits {public static int count(int n){int total=0;while(n!=0){n&=n-1;total++;}return total;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Integer: ");int n=sc.nextInt();System.out.println("Set bits: "+count(n));sc.close();}}